// Sent once connected and followed by a ping, whose pong is the barrier: every answer to the frame precedes it.
const sendOnConnect = (client: WebSocket, outbound: unknown): void => {
  client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
  client.send(JSON.stringify({type: 'ping', timestamp: 1}));
};

const askAfterConnect = async (url: string, outbound: unknown): Promise<{frames: Frame[]}> => {
  const client = connectClient(url);
  const frames: Frame[] = [];
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      if (frame.type === 'pong') return resolve();
      if (frame.type === 'connected') return sendOnConnect(client, outbound);
      frames.push(frame);
    });
  });
  return {frames};
};

